/**
 * Data Room API hooks — hand-written (not generated by orval).
 * Follows the same pattern as generated/api.ts.
 */
import { useMutation, useQuery } from "@tanstack/react-query";
import { customFetch } from "./custom-fetch";

// ── Types ─────────────────────────────────────────────────────────────────

export interface CaseDocument {
  id: number;
  case_id: number;
  doc_type: string;
  filename: string;
  storage_path: string;
  fiscal_year: string | null;
  extracted_data: Record<string, unknown> | null;
  source: string | null;
  created_at: string;
}

export interface DataRoomState {
  documents: CaseDocument[];
  extractedData: {
    financials?: Record<string, unknown>;
    research?: unknown[];
    peers?: unknown[];
    organogram?: Record<string, unknown>;
    security?: unknown[];
  } | null;
  completeness: number;
}

export interface Peer {
  symbol?: string;
  name: string;
  confirmed: boolean;
  suggested?: boolean;
  screenerData?: Record<string, unknown>;
}

// ── Query keys ────────────────────────────────────────────────────────────

export const getDataRoomQueryKey = (caseId: number) => ["dataRoom", caseId] as const;
export const getPeersQueryKey = (caseId: number) => ["dataRoomPeers", caseId] as const;

// ── GET data-room state ───────────────────────────────────────────────────

export const useGetDataRoom = (caseId: number) =>
  useQuery({
    queryKey: getDataRoomQueryKey(caseId),
    queryFn: () => customFetch<DataRoomState>(`/api/cases/${caseId}/data-room`),
    enabled: !!caseId,
  });

// ── POST fetch-reports ────────────────────────────────────────────────────

export const useFetchAnnualReports = () =>
  useMutation({
    mutationFn: ({ caseId, symbol, companyName }: { caseId: number; symbol: string; companyName?: string }) =>
      customFetch<{ ok: boolean; source: string; yearsFound: string[]; reportsLinked?: number; screenerUrl?: string }>(`/api/cases/${caseId}/data-room/fetch-reports`, {
        method: "POST",
        body: JSON.stringify({ symbol, companyName }),
        headers: { "Content-Type": "application/json" },
      }),
  });

// ── POST run-research ─────────────────────────────────────────────────────

export const useRunResearch = () =>
  useMutation({
    mutationFn: ({ caseId }: { caseId: number }) =>
      customFetch<{ ok: boolean; newItems: number; totalItems: number }>(`/api/cases/${caseId}/data-room/run-research`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
      }),
  });

// ── GET peers ─────────────────────────────────────────────────────────────

export const useGetPeers = (caseId: number) =>
  useQuery({
    queryKey: getPeersQueryKey(caseId),
    queryFn: () => customFetch<{ peers: Peer[] }>(`/api/cases/${caseId}/data-room/peers`),
    enabled: !!caseId,
  });

// ── PATCH peers ───────────────────────────────────────────────────────────

export const useUpdatePeers = () =>
  useMutation({
    mutationFn: ({ caseId, peers }: { caseId: number; peers: Peer[] }) =>
      customFetch<{ ok: boolean }>(`/api/cases/${caseId}/data-room/peers`, {
        method: "PATCH",
        body: JSON.stringify({ peers }),
        headers: { "Content-Type": "application/json" },
      }),
  });

// ── POST upload ───────────────────────────────────────────────────────────

export const useUploadDocument = () =>
  useMutation({
    mutationFn: ({ caseId, file, docType, fiscalYear, companyName }: {
      caseId: number;
      file: File;
      docType: string;
      fiscalYear?: string;
      companyName?: string;
    }) => {
      const formData = new FormData();
      formData.append("file", file);
      formData.append("docType", docType);
      if (fiscalYear) formData.append("fiscalYear", fiscalYear);
      if (companyName) formData.append("companyName", companyName);
      return customFetch<CaseDocument>(`/api/cases/${caseId}/data-room/upload`, {
        method: "POST",
        body: formData,
      });
    },
  });

// ── DELETE document ───────────────────────────────────────────────────────

export const useDeleteDocument = () =>
  useMutation({
    mutationFn: ({ caseId, docId }: { caseId: number; docId: number }) =>
      customFetch<void>(`/api/cases/${caseId}/data-room/documents/${docId}`, { method: "DELETE" }),
  });

// ── POST organogram-tree ──────────────────────────────────────────────────

export const useSaveOrganogramTree = () =>
  useMutation({
    mutationFn: ({ caseId, tree, summary }: { caseId: number; tree: unknown[]; summary: string }) =>
      customFetch<{ ok: boolean }>(`/api/cases/${caseId}/data-room/organogram-tree`, {
        method: "POST",
        body: JSON.stringify({ tree, summary }),
        headers: { "Content-Type": "application/json" },
      }),
  });

// ── Detailed CAM: annual-report analysis, group structure, RM inputs ──────

export interface GroupEntity {
  name: string;
  relation: string; // subsidiary | joint venture | associate
  country?: string | null;
  currency?: string | null;
  holding_pct?: number | null;
  turnover_cr?: number | null;
  pat_cr?: number | null;
  net_worth_cr?: number | null;
  business?: string | null;
}

export interface GroupStructure {
  borrower?: string;
  promoter_group?: string | null;
  promoter_holding_pct?: number | null;
  entities: GroupEntity[];
  verified?: boolean;
  source?: string;
  source_url?: string;
  pages?: number[];
}

export type RmInputs = Record<string, unknown>;

export const getRmInputsQueryKey = (caseId: number) => ["rmInputs", caseId] as const;

export const useAnalyseAnnualReport = () =>
  useMutation({
    mutationFn: ({ caseId }: { caseId: number }) =>
      customFetch<{ ok: boolean; fiscalYear?: string; pages?: number; topics: string[]; entities: number }>(
        `/api/cases/${caseId}/data-room/analyse-annual-report`,
        { method: "POST", headers: { "Content-Type": "application/json" } },
      ),
  });

export const useGetRmInputs = (caseId: number) =>
  useQuery({
    queryKey: getRmInputsQueryKey(caseId),
    queryFn: () => customFetch<{ inputs: RmInputs; updatedAt: string | null }>(`/api/cases/${caseId}/data-room/rm-inputs`),
    enabled: !!caseId,
  });

export const useSaveRmInputs = () =>
  useMutation({
    mutationFn: ({ caseId, inputs }: { caseId: number; inputs: RmInputs }) =>
      customFetch<{ ok: boolean }>(`/api/cases/${caseId}/data-room/rm-inputs`, {
        method: "PUT",
        body: JSON.stringify({ inputs }),
        headers: { "Content-Type": "application/json" },
      }),
  });

export const useSaveGroupStructure = () =>
  useMutation({
    mutationFn: ({ caseId, groupStructure }: { caseId: number; groupStructure: GroupStructure }) =>
      customFetch<{ ok: boolean }>(`/api/cases/${caseId}/data-room/group-structure`, {
        method: "PUT",
        body: JSON.stringify({ groupStructure }),
        headers: { "Content-Type": "application/json" },
      }),
  });

// ── Case workspace: CAM summary + audit trail ─────────────────────────────

export interface CamSummary {
  basis?: string;
  year?: string;
  metrics?: Record<string, number | null>;
  ebitda_margin_avg3?: number | null;
  rating?: string | null;
  grade?: string | null;
  grade_score?: number | null;
  assessment?: Record<string, string>;
  sources?: { label: string; url?: string | null }[];
  info_requests?: { priority: string; item: string; why: string }[];
  group_entities?: number;
  group_verified?: boolean;
  generated_at?: string;
  /** Sections the last run could not draft (AI provider busy); cleared as they are redrafted. */
  failed_sections?: string[];
}

export interface CaseWorkspace {
  summary: CamSummary | null;
  activity: { action: string; actor: string; timestamp: string }[];
}

export const getCaseWorkspaceQueryKey = (caseId: number) => ["caseWorkspace", caseId] as const;

export const useGetCaseWorkspace = (caseId: number) =>
  useQuery({
    queryKey: getCaseWorkspaceQueryKey(caseId),
    queryFn: () => customFetch<CaseWorkspace>(`/api/cases/${caseId}/workspace`),
    enabled: !!caseId,
  });

/** Redraft only the given sections (retry after some failed); the rest of the memo is untouched. */
export const useRedraftSections = () =>
  useMutation({
    mutationFn: ({ caseId, sections }: { caseId: number; sections: string[] }) =>
      customFetch<{ failedSections?: string[] }>(`/api/cases/${caseId}/generate`, {
        method: "POST",
        body: JSON.stringify({ sections }),
        headers: { "Content-Type": "application/json" },
      }),
  });

// ── Risk flag review (acknowledgement + mitigation) ──────────────────────

export const useUpdateRiskFlag = () =>
  useMutation({
    mutationFn: ({ caseId, flagId, isAcknowledged, mitigation }: { caseId: number; flagId: number; isAcknowledged?: boolean; mitigation?: string }) =>
      customFetch<{ id: number; isAcknowledged: boolean; mitigation: string | null }>(`/api/cases/${caseId}/risk-flags/${flagId}`, {
        method: "PATCH",
        body: JSON.stringify({ isAcknowledged, mitigation }),
        headers: { "Content-Type": "application/json" },
      }),
  });
